_DATA = json.loads(zlib.decompress(base64.b85decode(_BLOB)))
_ROUTES = {tuple(json.loads(k)): v for k, v in _DATA["routes"].items()}
_DEFAULT_KEY = tuple(json.loads(_DATA["default"]))
MOVES = {"NORTH": (0, -1), "SOUTH": (0, 1), "EAST": (1, 0), "WEST": (-1, 0)}
CROPS_FIRST = {"WHEAT": 2, "CARROT": 2, "TOMATO": 8, "STRAWBERRY": 10, "MELON": 10}


def _int(v, d=0):
    try:
        return int(v)
    except (TypeError, ValueError):
        return d


def _tile(tiles, pos):
    try:
        x, y = int(pos[0]), int(pos[1])
        return tiles[y][x]
    except (TypeError, ValueError, IndexError):
        return "LOCKED"


def _noop(act, tile, inv, seeds, pos):
    if not act:
        return True
    op = act[0]
    if op in MOVES:
        dx, dy = MOVES[op]
        x, y = int(pos[0]), int(pos[1])
        return not (0 <= x + dx < 10 and 0 <= y + dy < 10)
    if op == "PASS":
        return True
    shed = pos[0] in (4, 5) and pos[1] in (4, 5)
    if op == "DROP":
        return (not shed) or (not inv)
    if op == "PICKUP":
        return not shed
    if op == "PLACE":
        item = act[1] if len(act) > 1 else None
        if item in ("COW", "SHEEP") and isinstance(tile, dict) and tile.get("kind") == "PASTURE" and tile.get("animal") is None:
            return _int(inv.get(item), 0) <= 0
        if item == "GOOSE" and isinstance(tile, dict) and tile.get("kind") == "COOP" and tile.get("animal") is None:
            return _int(inv.get("GOOSE"), 0) <= 0
        return (not shed) or _int(inv.get(item), 0) <= 0
    if tile == "LOCKED":
        return True
    kind = tile.get("kind") if isinstance(tile, dict) else None
    animal = isinstance(tile, dict) and tile.get("animal") is not None
    if op == "PLANT":
        return tile is not None or _int(seeds.get(act[1] if len(act) > 1 else None), 0) <= 0
    if op == "WATER":
        return kind != "PLANT" or bool(tile.get("watered_today"))
    if op == "HARVEST":
        return (not isinstance(tile, dict)) or _int(tile.get("yield_units"), 0) <= 0
    if op == "FERTILIZE":
        return kind != "PLANT" or _int(inv.get("FERTILIZER"), 0) <= 0
    if op == "DIG":
        return tile is None or animal
    if op in ("BUILD_COOP", "BUILD_PASTURE"):
        return tile is not None
    if op == "FEED":
        return (not animal) or bool(tile.get("fed_today")) or _int(inv.get("WHEAT"), 0) <= 0
    if op == "COLLECT_FERTILIZER":
        return (not animal) or (not tile.get("fertilizer_available"))
    if op == "CARE":
        return (not animal) or bool(tile.get("cared_today"))
    return True


def _walk(pos, target):
    x, y = int(pos[0]), int(pos[1])
    tx, ty = target
    if x != tx:
        return ["EAST" if x < tx else "WEST"]
    if y != ty:
        return ["SOUTH" if y < ty else "NORTH"]
    return None


def _scan(farm, day, invs):
    hungry, water, harvest, weeds, fert = [], [], [], [], []
    tiles = farm.get("tiles") or []
    for y, row in enumerate(tiles):
        for x, tile in enumerate(row):
            pos = (x, y)
            if tile is None or tile == "LOCKED" or not isinstance(tile, dict):
                continue
            if tile.get("kind") == "WEED":
                weeds.append(pos)
                continue
            if tile.get("animal"):
                if not tile.get("fed_today"):
                    hungry.append(pos)
                if tile.get("fertilizer_available"):
                    fert.append(pos)
                if _int(tile.get("yield_units"), 0) > 0:
                    harvest.append(pos)
            if tile.get("kind") == "PLANT":
                crop = tile.get("crop")
                age = day - _int(tile.get("planted_day"), 0)
                first = CROPS_FIRST.get(crop, 0)
                if _int(tile.get("yield_units"), 0) > 0 and age >= first:
                    harvest.append(pos)
                if not tile.get("watered_today"):
                    water.append(pos)
    wheat_holders = [i for i, inv in enumerate(invs) if _int(inv.get("WHEAT"), 0) > 0]
    return hungry, water, harvest, weeds, fert, wheat_holders


def _nearest(pos, targets):
    best = None
    best_d = None
    for t in targets:
        d = abs(int(pos[0]) - t[0]) + abs(int(pos[1]) - t[1])
        if best_d is None or d < best_d:
            best, best_d = t, d
    return best


def _repair_unit(act, pos, tile, inv, seeds, hungry, water, harvest, weeds, claimed):
    if not _noop(act, tile, inv, seeds, pos):
        return list(act)
    pos_t = (int(pos[0]), int(pos[1]))
    if pos_t in harvest and pos_t not in claimed:
        claimed.add(pos_t)
        return ["HARVEST"]
    if pos_t in hungry and _int(inv.get("WHEAT"), 0) > 0 and pos_t not in claimed:
        claimed.add(pos_t)
        return ["FEED"]
    if pos_t in water and pos_t not in claimed:
        claimed.add(pos_t)
        return ["WATER"]
    if isinstance(tile, dict) and tile.get("kind") == "WEED":
        return ["DIG"]
    for bucket, op, need_wheat in (
        (hungry, "FEED", True),
        (harvest, "HARVEST", False),
        (water, "WATER", False),
        (weeds, "DIG", False),
    ):
        if need_wheat and _int(inv.get("WHEAT"), 0) <= 0:
            continue
        target = _nearest(pos, [p for p in bucket if p not in claimed])
        if target is None:
            continue
        walk = _walk(pos, target)
        if walk:
            return walk
        claimed.add(target)
        return [op]
    return list(act) if act else ["PASS"]


def _clamp_market(market, shed):
    out = []
    stock = dict(shed)
    for order in market or []:
        if not order:
            continue
        order = list(order)
        if order[0] == "SELL" and len(order) >= 3:
            item = order[1]
            have = _int(stock.get(item), 0)
            qty = min(max(0, _int(order[2])), have)
            if qty <= 0:
                continue
            stock[item] = have - qty
            order[2] = qty
        out.append(order)
        if len(out) >= 10:
            break
    return out


def _pick_route(observation, step):
    shops = tuple((observation.get("town") or {}).get("unlocked_shops") or [])[:2]
    if step >= 144 and len(shops) >= 2 and shops in _ROUTES:
        return shops
    if step >= 72 and shops and shops[0:1]:
        for key in _ROUTES:
            if key and key[0] == shops[0]:
                return key
    if _DEFAULT_KEY in _ROUTES:
        return _DEFAULT_KEY
    return next(iter(_ROUTES))


def agent(observation, configuration=None):
    player = _int(observation.get("player"), 0)
    farm = observation["farms"][player]
    private = observation.get("private") or {}
    step = _int(observation.get("step"), 0)
    day = _int(observation.get("day"), step // 24)
    route = _pick_route(observation, step)
    tape = _ROUTES[route]
    raw = tape[step] if 0 <= step < len(tape) else {"farmer": ["PASS"], "hands": [], "market": []}
    farmer = list(raw.get("farmer") or ["PASS"])
    hands = [list(h) for h in (raw.get("hands") or [])]
    n_hands = len(farm.get("hands") or [])
    while len(hands) < n_hands:
        hands.append(["PASS"])
    hands = hands[:n_hands]
    tiles = farm.get("tiles") or []
    seeds = private.get("seeds") or {}
    invs = list(private.get("inventories") or [{}])
    while len(invs) < 1 + n_hands:
        invs.append({})
    positions = [farm.get("farmer")] + list(farm.get("hands") or [])
    hungry, water, harvest, weeds, fert, _ = _scan(farm, day, invs)
    claimed = set()
    units = [farmer] + hands
    for i, pos in enumerate(positions):
        if pos is None:
            continue
        tile = _tile(tiles, pos)
        inv = invs[i] if i < len(invs) else {}
        units[i] = _repair_unit(units[i], pos, tile, inv, seeds, hungry, water, harvest, weeds, claimed)
    market = _clamp_market(raw.get("market") or [], private.get("shed") or {})
    return {"farmer": units[0], "hands": units[1:], "market": market}
